using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _controller = new StudentsController(_context);
        // Setup TempData for controller
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), new SessionStateTempDataProvider(new SessionStore()));
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult_WithStudentsList()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Theory]
    [InlineData("name_desc", "Anand")] // Descending by last name → Anand first
    [InlineData("", "Alexander")]       // Default ascending → Alexander first
    public void Index_SortOrder_SortsCorrectly(string sortOrder, string expectedFirstLastName)
    {
        var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(expectedFirstLastName, model.First().LastName);
    }

    [Fact]
    public void Index_DateSort_SortsByEnrollmentDate()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Alexander", model.First().LastName); // 2010 is earliest
    }

    [Fact]
    public void Index_DateDescSort_SortsByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model.First().LastName); // 2013 is latest
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model.First().LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model.First().FirstMidName);
    }

    [Fact]
    public void Index_NewSearchString_ResetsPageTo1()
    {
        // When searchString is not null, page should reset to 1
        var result = _controller.Index(null, null, "A", 5) as ViewResult;

        Assert.NotNull(result);
        // ViewBag.CurrentFilter should be the search string
        Assert.Equal("A", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "existing", null, 2) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("existing", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithStudentHavingTodaysDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(4, _context.Students.Count());
    }

    [Fact]
    public void Create_Post_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_EnrollmentDateOutOfRange_ReturnsView()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = _context.Students.Find(1)!;
        student.FirstMidName = "Updated";
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(2, _context.Students.Count());
    }

    // Simple SessionStore to satisfy TempData requirement
    private class SessionStore : ISessionStore, ITempDataProvider
    {
        public IDictionary<string, object?> LoadTempData(HttpContext context) => new Dictionary<string, object?>();
        public void SaveTempData(HttpContext context, IDictionary<string, object?> values) { }
    }
}

