using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanCreateInMemory()
    {
        using var context = TestDbContextFactory.Create();
        Assert.NotNull(context);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        using var context = TestDbContextFactory.Create();
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("Student", retrieved.LastName);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveCourse()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 100, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.First();
        Assert.Equal("Test Course", retrieved.Title);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContextFactory.Create();

        var instructor = new Instructor { FirstMidName = "Test", LastName = "Inst", HireDate = DateTime.Now };
        context.Instructors.Add(instructor);
        var dept = new Department { Name = "Dept", Budget = 100, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 200, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments.First();
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void SchoolContext_CanAddEnrollment()
    {
        using var context = TestDbContextFactory.Create();
        var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
        context.Students.Add(student);
        var dept = new Department { Name = "D", Budget = 1, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 300, Title = "C", Credits = 1, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.First();
        Assert.Equal(Grade.A, retrieved.Grade);
    }

    [Fact]
    public void DbInitializer_SeedsData_WhenEmpty()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.True(context.Students.Any());
        Assert.True(context.Instructors.Any());
        Assert.True(context.Departments.Any());
        Assert.True(context.Courses.Any());
    }

    [Fact]
    public void DbInitializer_DoesNotReseed_WhenDataExists()
    {
