using ContosoUniversity.Models;
using System;
using Xunit;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    [Fact]
    public void Person_FullName_ReturnsConcatenatedName()
    {
        var student = new Student { FirstMidName = "John", LastName = "Doe" };

        Assert.Equal("Doe, John", student.FullName);
    }

    [Fact]
    public void Instructor_FullName_ReturnsConcatenatedName()
    {
        var instructor = new Instructor { FirstMidName = "Jane", LastName = "Smith" };

        Assert.Equal("Smith, Jane", instructor.FullName);
    }

    [Fact]
    public void Student_InheritsFromPerson()
    {
        var student = new Student { ID = 1, FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };

        Assert.IsAssignableFrom<Person>(student);
    }

    [Fact]
    public void Instructor_InheritsFromPerson()
    {
        var instructor = new Instructor { ID = 1, FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };

        Assert.IsAssignableFrom<Person>(instructor);
    }

    [Fact]
    public void Notification_PropertiesSetCorrectly()
    {
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = DateTime.Now,
            CreatedBy = "admin",
            IsRead = false,
            ReadAt = null
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Test message", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    [Fact]
    public void Course_PropertiesSetCorrectly()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/uploads/test.jpg"
        };

        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
    }

    [Fact]
    public void Department_PropertiesSetCorrectly()
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "English",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 1
        };

        Assert.Equal(1, dept.DepartmentID);
        Assert.Equal("English", dept.Name);
        Assert.Equal(350000m, dept.Budget);
    }

    [Fact]
    public void Enrollment_GradeCanBeNull()
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 100,
            StudentID = 1,
            Grade = null
        };

        Assert.Null(enrollment.Grade);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
